n_golfers = 30
n_groups = 10
n_weeks = 7

# Verify group sizes
for w in range(n_weeks):
    counts = [0] * n_groups
    for p in range(n_golfers):
        g = sol[w*30 + p]
        counts[g] += 1
    for c in counts:
        if c != 3:
            print(f"Week {w}: group count {counts} NOT all 3")
            break
    else:
        print(f"Week {w}: OK, groups={counts}")

# Verify pair constraint
pair_weeks = {}
for w in range(n_weeks):
    groups = sol[w*30 : (w+1)*30]
    for g in range(n_groups):
        members = [p for p in range(n_golfers) if groups[p] == g]
        if len(members) != 3:
            print(f"Week {w} group {g} has {len(members)} members: {members}")
        for i in range(len(members)):
            for j in range(i+1, len(members)):
                pair = (members[i], members[j])
                if pair in pair_weeks:
                    pair_weeks[pair].append(w)
                else:
                    pair_weeks[pair] = [w]

violations = [(pair, weeks) for pair, weeks in pair_weeks.items() if len(weeks) > 1]
if violations:
    print(f"Violations: {violations}")
else:
    print("No pair violations!")

print(f"Total pairs: {len(pair_weeks)}")
print(f"Expected: {n_weeks * n_groups * 3 * 2 // 2} = {n_weeks * n_groups * 3}")
